function [D,L_N]=problem1(F,t)
% F是时间×100的矩阵
% t是需要计算第t秒的损失值
% D_total是t秒的疲劳损伤值1×100风机
% L_N是t秒的等效疲劳载荷1×100风机
max_load = 50000000;
N_l=42565440.4361;
m=10;
C=9.77*10^70;
W=F(1:t,:);
if t==1
D(1,:)=0;
L_N(1,:) = (sum(W(t,:).^m) / N_l)^(1/m);
elseif t==2
s_amp=abs(W(2,:)-W(1,:));
s_N = (C ./ s_amp.^m);
D(1,:)=1./s_N;
L_N(1,:) = (sum(s_amp.^m) / N_l)^(1/m);
else
  [D(1,:),L_N(1,:)] = cacul_damage(W, max_load, N_l, m, C);
end
end

function [D, L] = cacul_damage(x, max_load, N_life, m, C)
for q=1:100
   data=x(:,q);
   [c] = rainflow(data);
   count=c(:,1);
   cycles=c(:,2);
  means=c(:,3);

 % 记录载荷幅值和循环次数
  n_cycles = size(cycles, 1); % 循环次数
  S_amplitudes = abs(cycles(:, 1)); % 应力幅值
  S_means = means; % 应力均值
  S_corrected = zeros(n_cycles, 1);
   for i = 1:n_cycles
     S_ai = S_amplitudes(i); % 幅值
    S_mi = S_means(i);  % 均值
     S_corrected(i) = S_ai / (1 - S_mi / max_load); % Goodman修正
  end


                                                   58

  D_total = 0;
   for i = 1:n_cycles
    S_i = S_corrected(i);
   N_F = (C / S_i^m);
    n_F = count(i);
   D_F = n_F / N_F;
     D_total = D_total + D_F;
  end

  L_N = (sum(S_corrected.^m) / N_life)^(1/m);
D(1,q)=D_total;
L(1,q)=L_N;
end


